mapper.select:
SELECT COUNT(CASE WHEN (JOIN_DM.WIDTH * JOIN_DM.HEIGHT < 921690) THEN 1 END) AS hd_data_cnt , COUNT(CASE WHEN (JOIN_DM.WIDTH * JOIN_DM.HEIGHT BETWEEN 921690 AND 2073600) THEN 1 END) AS fhd_data_cnt , COUNT(CASE WHEN (JOIN_DM.WIDTH * JOIN_DM.HEIGHT BETWEEN 2073601 AND 3686400) THEN 1 END) AS qhd_data_cnt , COUNT(CASE WHEN (JOIN_DM.WIDTH * JOIN_DM.HEIGHT > 3686400) THEN 1 END) AS fk_data_cnt
FROM ( SELECT DT.DATA_ID , DT.WIDTH , DT.HEIGHT FROM DATA AS DT LEFT JOIN META AS M ON DT.DATA_ID = M.DATA_ID WHERE (DT.WIDTH IS NOT NULL AND DT.HEIGHT IS NOT NULL) AND DT.DATASET_ID = #{dataset_id}
AND M.LABEL = #{label}
GROUP BY DT.DATA_ID ) AS JOIN_DM

SELECT LABEL , COUNT(*) AS class_cnt FROM META WHERE DATA_ID IN ( SELECT DATA_ID FROM DATA WHERE DATASET_ID = #{dataset_id} )
AND LABEL = #{label}
GROUP BY LABEL
